import React, { useState, useEffect, useMemo } from "react";
import styled from "styled-components";
import { useTranslation } from "react-i18next";
import { apiUpdateUserById } from "../service/user";
import { useNotice } from "../context/NoticeContext";

const PopupContainer = styled.div`
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 50%;
  padding: 20px;
  background-color: white;
  border-radius: 8px;
  border: 3px solid rgb(162, 166, 171); 
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
  z-index: 1000;
  transition: box-shadow 0.3s ease, transform 0.3s ease;
`;

const Title = styled.h2`
  text-align: center;
  margin-bottom: 20px;
  position: relative;
  font-size: 30px;
  font-weight: bold;
`;

const CloseButton = styled.button`
  position: absolute;
  top: 10px;
  right: 10px;
  background: none;
  border: none;
  font-size: 40px;
  color: #aaa;
  cursor: pointer;

  &:hover {
    color: #f00;
  }
`;

const InfoWrapper = styled.div`
  display: flex;
  flex-direction: column;
  gap: 15px;
`;

const InfoRow = styled.div`
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 20px;
`;

const Label = styled.label`
  font-weight: bold;
  width: 150px;
  text-align: left;
`;

const InputField = styled.input`
  padding: 10px;
  margin: 5px 0;
  border: 1px solid #ccc;
  border-radius: 4px;
  width: 60%;
`;

const ValueText = styled.span`
  width: 60%;
  text-align: left;
  padding: 10px;
`;

const ButtonWrapper = styled.div`
  display: flex;
  justify-content: space-between;
  margin-top: 20px;
`;

const Button = styled.button`
  padding: 10px 15px;
  background-color: #007bff;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;

  &:disabled {
    background-color: #ccc;
    cursor: not-allowed;
  }

  &:hover {
    background-color: #0056b3;
  }
`;

const UserInfoPopup = ({ openPopup, closePopup, userInfo }) => {
  const { t } = useTranslation();
  const [isEditing, setIsEditing] = useState(false);
  const [editableInfo, setEditableInfo] = useState(userInfo);
  const [errors, setErrors] = useState({});
  const { showNotice } = useNotice();

  useEffect(() => {
    setEditableInfo(userInfo);
  }, [userInfo]);

  const fieldMap = useMemo(() => ({
    email: t("userInfoComponent.email"),
    username: t("userInfoComponent.name"),
    address: t("userInfoComponent.address"),
    phone: t("userInfoComponent.phone"),
    birthday: t("userInfoComponent.birthday"),
    gender: t("userInfoComponent.gender"),
    career: t("userInfoComponent.career"),
    workplace: t("userInfoComponent.workplace"),
  }), [t]);

  const validateFields = () => {
    const newErrors = {};

    if (!editableInfo.email || !/\S+@\S+\.\S+/.test(editableInfo.email)) {
      newErrors.email = t("userInfoComponent.error.invalid_email");
    }

    if (!editableInfo.username) {
      newErrors.username = t("userInfoComponent.error.name_required");
    }

    if (!editableInfo.phone || !/^0\d{9}$/.test(editableInfo.phone)) {
      newErrors.phone = t("userInfoComponent.error.invalid_phone");
    }

    if (!editableInfo.address) {
      newErrors.address = t("userInfoComponent.error.address_required");
    }

    if (!editableInfo.birthday) {
      newErrors.birthday = t("userInfoComponent.error.birthday_required");
    }

    if (!editableInfo.gender) {
      newErrors.gender = t("error.gender_required");
    }

    if (!editableInfo.career) {
      newErrors.career = t("error.career_required");
    }

    if (!editableInfo.workplace) {
      newErrors.workplace = t("error.workplace_required");
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setEditableInfo((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleConfirm = async () => {
    if (!validateFields()) return;

    try {
      const { _id, email, username, phone, address, birthday, gender, career, workplace } = editableInfo;
      await apiUpdateUserById(_id, email, username, phone, address, birthday, gender, career, workplace);
      setIsEditing(false);
      closePopup();
      showNotice(1, t("success.update_user"));
    } catch (error) {
      alert(t("error.update_failed") + ": " + error);
    }
  };

  return (
    openPopup && (
      <PopupContainer>
        <Title>{t("userInfo.title")}</Title>
        <CloseButton onClick={closePopup}>×</CloseButton>
        <InfoWrapper>
          {Object.entries(fieldMap).map(([key, label]) => (
            <InfoRow key={key}>
              <Label>{label}</Label>
              {isEditing ? (
                <div style={{ width: "60%" }}>
                  {key === "gender" ? (
                    <>
                      <select
                        name="gender"
                        value={editableInfo.gender || ""}
                        onChange={handleChange}
                        style={{
                          padding: "10px",
                          margin: "5px 0",
                          border: "1px solid #ccc",
                          borderRadius: "4px",
                          width: "80px",
                        }}
                      >
                        <option value="">{t("user.gender_placeholder")}</option>
                        <option value="Nam">{t("user.male")}</option>
                        <option value="Nữ">{t("user.female")}</option>
                      </select>
                      {errors[key] && (
                        <div style={{ color: "red", fontSize: "13px", marginTop: "-5px" }}>
                          {errors[key]}
                        </div>
                      )}
                    </>
                  ) : (
                    <>
                      <InputField
                        type={key === "birthday" ? "date" : "text"}
                        name={key}
                        value={
                          key === "birthday" && editableInfo[key]
                            ? editableInfo[key].slice(0, 10)
                            : editableInfo?.[key] || ""
                        }
                        onChange={handleChange}
                      />
                      {errors[key] && (
                        <div style={{ color: "red", fontSize: "13px", marginTop: "-5px" }}>
                          {errors[key]}
                        </div>
                      )}
                    </>
                  )}
                </div>
              ) : (
                <ValueText>
                  {key === "birthday" && editableInfo[key]
                    ? new Date(editableInfo[key]).toISOString().split("T")[0]
                    : editableInfo?.[key] || ""}
                </ValueText>
              )}
            </InfoRow>
          ))}
        </InfoWrapper>
        <ButtonWrapper>
          <Button onClick={() => setIsEditing(true)} disabled={isEditing}>
            {t("userInfo.edit")}
          </Button>
          <Button onClick={handleConfirm} disabled={!isEditing}>
            {t("userInfo.confirm")}
          </Button>
        </ButtonWrapper>
      </PopupContainer>
    )
  );
};

export default UserInfoPopup;
